mapper.select:

		/* selectWorkerCount - Lee JiSeob */

		SELECT

			COUNT(*) AS CNT 

		FROM SCA100 C /* 종사자 */

		LEFT JOIN SAA200 D /* 사용자 */ ON D.ENFSN_NO = C.ENFSN_NO

		LEFT JOIN SAA000 E /* 통합기관 */ ON E.INST_NO = C.OGDP_INST_NO

        LEFT JOIN SAB230 F /* 사용자별 기관 권한 */ ON F.USER_ID = D.USER_ID AND F.MAIST_YN = 'Y'





				AND C##RG.DEC_B64(C.FLNM_ENCPT) LIKE '%' || #{FLNM_ENCPT} || '%'




                AND REPLACE(C##RG.DEC_B64(C.MBL_TELNO_ENCPT), '-', '') LIKE '%' || REPLACE(#{MBL_TELNO_ENCPT}, '-', '') || '%'




				AND C##RG.DEC_B64(C.EML_ADDR_ENCPT) LIKE '%' || #{EML_ADDR_ENCPT} || '%'




				AND C.SXDC_SE_CD = #{SXDC_SE_CD}




				AND C.NCKN_NM LIKE '%' || #{NCKN_NM} || '%'




				AND D.USER_ID LIKE '%' || #{USER_ID} || '%'




                AND D.USER_ID_USE_SE_CD = #{USER_ID_USE_SE_CD}




                AND E.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}




                AND E.INST_TYPE_SE_CD = #{INST_TYPE_SE_CD}




                AND E.INST_NM LIKE '%' || #{INST_NM} || '%'




                AND F.GROUP_AUTHRT_SE_CD = #{GROUP_AUTHRT_SE_CD}




                AND F.AUTHRT_SE_CD = #{AUTHRT_SE_CD}




                AND F.SYS_MNGR_YN = #{SYS_MNGR_YN}

/* selectWorker - Lee JiSeob */
SELECT SEQ, FLNM_ENCPT, MBL_TELNO_ENCPT, EML_ADDR_ENCPT, SXDC_SE_CD, BRTH_YMD, NCKN_NM, ENFSN_NO, USER_ID, USER_ID_USE_SE_CD, DEL_YN, INST_NM, INST_TYPE_SE_CD, UNT_TASKWK_SE_CD, /* 기관명, 기관유형, 단위업무구분코드 */ GROUP_AUTHRT_SE_CD, AUTHRT_SE_CD, SYS_MNGR_YN FROM ( SELECT ROWNUM AS SEQ, FLNM_ENCPT, MBL_TELNO_ENCPT, EML_ADDR_ENCPT, SXDC_SE_CD, BRTH_YMD, NCKN_NM, ENFSN_NO, USER_ID, USER_ID_USE_SE_CD, DEL_YN, INST_NM, INST_TYPE_SE_CD, UNT_TASKWK_SE_CD, /* 기관명, 기관유형, 단위업무구분코드 */ GROUP_AUTHRT_SE_CD, AUTHRT_SE_CD, SYS_MNGR_YN FROM ( SELECT
C##RG.DEC_B64(C.FLNM_ENCPT) AS FLNM_ENCPT, C##RG.DEC_B64(C.MBL_TELNO_ENCPT) AS MBL_TELNO_ENCPT, C##RG.DEC_B64(C.EML_ADDR_ENCPT) AS EML_ADDR_ENCPT, C.SXDC_SE_CD, C.BRTH_YMD, C.NCKN_NM, C.ENFSN_NO, D.USER_ID, D.USER_ID_USE_SE_CD, C.DEL_YN, E.INST_NM, /* 기관명 */ E.INST_TYPE_SE_CD, /* 기관유형 */ E.UNT_TASKWK_SE_CD, /* 단위업무구분코드 */ F.GROUP_AUTHRT_SE_CD, F.AUTHRT_SE_CD, F.SYS_MNGR_YN
FROM SCA100 C /* 종사자 */
LEFT JOIN SAA200 D /* 사용자 */ ON D.ENFSN_NO = C.ENFSN_NO
LEFT JOIN SAA000 E /* 통합기관 */ ON E.INST_NO = C.OGDP_INST_NO
LEFT JOIN SAB230 F /* 사용자별 기관 권한 */ ON F.USER_ID = D.USER_ID AND F.MAIST_YN = 'Y'
AND C.FLNM_ENCPT = C##RG.ENC_B64(#{FLNM_ENCPT})
AND REPLACE(C##RG.DEC_B64(C.MBL_TELNO_ENCPT), '-', '') LIKE '%' || REPLACE(#{MBL_TELNO_ENCPT}, '-', '') || '%'
AND C##RG.DEC_B64(C.EML_ADDR_ENCPT) LIKE '%' || #{EML_ADDR_ENCPT} || '%'
AND C.SXDC_SE_CD = #{SXDC_SE_CD}
AND C.NCKN_NM LIKE '%' || #{NCKN_NM} || '%'
AND D.USER_ID LIKE '%' || #{USER_ID} || '%'
AND D.USER_ID_USE_SE_CD = #{USER_ID_USE_SE_CD}
AND E.UNT_TASKWK_SE_CD = #{UNT_TASKWK_SE_CD}
AND E.INST_TYPE_SE_CD = #{INST_TYPE_SE_CD}
AND E.INST_NM LIKE '%' || #{INST_NM} || '%'
AND F.GROUP_AUTHRT_SE_CD = #{GROUP_AUTHRT_SE_CD}
AND F.AUTHRT_SE_CD = #{AUTHRT_SE_CD}
AND F.SYS_MNGR_YN = #{SYS_MNGR_YN}
ORDER BY C.FRST_REG_DT DESC ) X1 ) X2 WHERE SEQ >= #{START_IDX} AND SEQ <= #{LAST_IDX}


/* selectYouthGuardianCount - Lee JiSeob */

SELECT 
    COUNT(*) AS CNT

FROM 
    SCA200 C /* 청소년 보호자 */
    LEFT JOIN SAA200 D /* 사용자 */ ON D.YNGBGS_PRTCR_NO = C.YNGBGS_PRTCR_NO

/*
WHERE
    C.DEL_YN = 'N'
    AND (D.JOIN_APRV_YN IS NULL OR JOIN_APRV_YN = 'Y')
*/




    AND C.YNGBGS_PRTCR_SE_CD = #{YNGBGS_PRTCR_SE_CD}




    AND C.FLNM_ENCPT = C##RG.ENC_B64(#{FLNM})




    AND C.MBL_TELNO_ENCPT = C##RG.ENC_B64(#{MBL_TELNO})




    AND C.EML_ADDR_ENCPT = C##RG.ENC_B64(#{EML_ADDR})




    AND C.SXDC_SE_CD = #{SXDC_SE_CD}




    AND C.RGN_CD = #{RGN_CD}




    AND D.USER_ID LIKE '%' || #{USER_ID} || '%'




    AND D.USER_ID_USE_SE_CD = #{USER_ID_USE_SE_CD}

/* selectYouthGuardian - Lee JiSeob */
SELECT C.YNGBGS_PRTCR_NO, C.INDV_IDNTFC_NO, C.YNGBGS_PRTCR_SE_CD, C.FLNM_ENCPT, C##RG.DEC_B64(C.FLNM_ENCPT) AS FLNM, C##RG.DEC_B64(C.FLNM_ENCPT) AS FLNM_MASKING, C.SXDC_SE_CD, C.BRTH_YMD, C.BRTH_YMD AS BRTH_YMD_MASKING, C.WRD_TELNO, C.MBL_TELNO_ENCPT, C##RG.DEC_B64(C.MBL_TELNO_ENCPT) AS MBL_TELNO, C##RG.DEC_B64(C.MBL_TELNO_ENCPT) AS MBL_TELNO_MASKING, C.EML_ADDR_ENCPT, C##RG.DEC_B64(C.EML_ADDR_ENCPT) AS EML_ADDR, C##RG.DEC_B64(C.EML_ADDR_ENCPT) AS EML_ADDR_MASKING, C.ZIP, C.PST_ADDR, C.DADDR, C.STTY_AGT_NM_ENCPT, C##RG.DEC_B64(C.STTY_AGT_NM_ENCPT) AS STTY_AGT_NM, C.STTY_AGT_CTTPC_TELNO, C.OCCP_NM, C.RGN_CD, C.INFO_PVSN_AGRE_YN1, C.INFO_PVSN_AGRE_YN2, C.DEL_YN, C.QLFC_INFO_MNG_NO, C.PSPT_ENG_FLNM_ENCPT, C##RG.DEC_B64(C.PSPT_ENG_FLNM_ENCPT) AS PSPT_ENG_FLNM, C.TRPR_BCRN_TYPE_SE_CD, C.TRPR_BCRN_TYPE_RM_NM, C.NLTY_NTN_SE_CD, C.ENTCNY_YMD, C.BRTH_NTN_SE_CD, C.GROWTH_NTN_SE_CD, C.VISA_TYPE_SE_CD, C.HANAWO_PENU_NO, C.RELGN_SE_CD, C.FRST_RGTR_ID, TO_CHAR(C.FRST_REG_DT, 'YYYY-MM-DD HH24:MI:SS') AS FRST_REG_DT, C.LAST_MDFR_ID, TO_CHAR(C.LAST_MDFCN_DT, 'YYYY-MM-DD HH24:MI:SS') AS LAST_MDFCN_DT,
D.USER_ID, D.USER_ID_USE_SE_CD, D.JOIN_RJCT_CS_CN
FROM SCA200 C /* 청소년 보호자 */ LEFT JOIN SAA200 D /* 사용자 */ ON D.YNGBGS_PRTCR_NO = C.YNGBGS_PRTCR_NO
/* WHERE C.DEL_YN = 'N' AND (D.JOIN_APRV_YN IS NULL OR JOIN_APRV_YN = 'Y') */
AND C.YNGBGS_PRTCR_SE_CD = #{YNGBGS_PRTCR_SE_CD}
AND C.FLNM_ENCPT = C##RG.ENC_B64(#{FLNM})
AND C.MBL_TELNO_ENCPT = C##RG.ENC_B64(#{MBL_TELNO})
AND C.EML_ADDR_ENCPT = C##RG.ENC_B64(#{EML_ADDR})
AND C.SXDC_SE_CD = #{SXDC_SE_CD}
AND C.RGN_CD = #{RGN_CD}
AND D.USER_ID LIKE '%' || #{USER_ID} || '%'
AND D.USER_ID_USE_SE_CD = #{USER_ID_USE_SE_CD}
ORDER BY FRST_REG_DT DESC
OFFSET #{OFFSET_IDX} ROWS FETCH NEXT #{ROW_COUNT} ROWS ONLY

/* selectYngbgsPrtcrNo - Lee JiSeob */
SELECT ISRY_APP.SA_FN_GET_RENU_NO('YP', #{USER_ID}, '') AS YNGBGS_PRTCR_NO
FROM DUAL
